package com.autoops.execution.controller;import com.autoops.execution.entity.ApprovalRequest;import com.autoops.execution.service.ApprovalService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/approvals")public class ApprovalController{private final ApprovalService service;public ApprovalController(ApprovalService s){service=s;}@GetMapping("/pending")public List<ApprovalRequest> pending(){return service.pending();}public record Decision(boolean approve,boolean highRiskConfirmed){}@PostMapping("/{id}/decision")public ApprovalRequest decide(@PathVariable Long id,@RequestBody Decision d){return service.decide(id,d.approve(),d.highRiskConfirmed());}}
